#!/usr/bin/env bash
# Generates every raw sheet for Mac Kiem Luc, one request at a time. Usage: MK_KEYS="key" tools/art.sh [name ...]
S="Style: traditional Chinese ink wash painting (sumi-e) game art, bold expressive black brush outlines, muted desaturated colours with a single vermilion red accent, rich detail, layered clothing with 3 to 4 shades."
F="Each figure full body, seen from a three-quarter top-down camera like an isometric action game, facing right, clearly separated from the others with wide gaps, on a flat solid pure magenta #FF00FF background, no ground, no cast shadow, no text, no frame."
want() { [ $# -eq 0 ] && return 0; for n in "$@"; do [ "$n" = "$W" ] && return 0; done; return 1; }
g() { W=$1; if want "${ARGS[@]}"; then tools/gen.sh "$1" "$2" "$3"; sleep 2; fi; }
ARGS=("$@")
g hero "The same wandering swordsman drawn four times in one row: wide conical bamboo hat, tattered dark indigo robe, long vermilion scarf, straight jian sword. Pose 1 standing ready with sword lowered. Pose 2 running. Pose 3 in the middle of a wide horizontal slash, sword extended forward. Pose 4 low dashing lunge with scarf trailing." "$S $F"
g foes1 "Four different ancient wuxia enemies in one row: 1 a scruffy mountain bandit with a curved saber, 2 a masked archer drawing a bow, 3 a soldier with a long red-tasselled spear, 4 a hooded assassin in black with twin daggers." "$S $F"
g foes2 "Four different ancient wuxia enemies in one row: 1 a huge bare-chested brute with a great iron hammer, 2 a fallen monk in torn grey robes with an iron staff, 3 a poison mistress in dark green holding a paper umbrella, 4 a soldier crouching behind a big round rattan shield with a short blade." "$S $F"
g bosses "Three imposing wuxia boss characters in one row, each large: 1 a bandit king wearing a tiger pelt with a huge nine-ring broadsword, 2 a blind old abbot in ochre robes with giant prayer beads and a bronze bell, 3 a white-haired sword saint in flowing white robes with a long thin sword." "$S $F"
g npcs "Three friendly ancient wuxia characters in one row: 1 a travelling merchant carrying a tall wooden pack frame full of goods, 2 an old tea master sitting beside a small clay stove and teapot, 3 an old hermit master with a long white beard leaning on a gnarled staff." "$S $F"
g props "Eight separate objects in two rows of four: a cluster of green bamboo stalks, a mossy boulder, a stone lantern, a broken temple pillar, a snow-covered pine tree, a large clay wine jar, a wooden treasure chest with iron bands, a small red roadside shrine." "$S Each object seen from a three-quarter top-down camera, clearly separated with wide gaps, on a flat solid pure magenta #FF00FF background, no ground, no cast shadow, no text."
G="Top-down orthographic view of game arena ground seen from directly above, a wide EMPTY open floor filling the middle 80 percent of the image with no objects and no people on it, scenery only around the outer border. No text, no characters, no UI."
g bg1 "A clearing in a misty bamboo forest: pale beaten earth and scattered fallen leaves, ringed by dense bamboo, rocks and mist at the edges." "$S $G"
g bg2 "The courtyard of a ruined mountain temple at dusk: cracked grey flagstones with moss and faded painted circle, ringed by broken walls, pillars, red banners and incense burners at the edges." "$S $G"
g bg3 "A snowy mountain summit terrace at night: pale blue-white snow over old stone, ringed by frosted pines, cliffs and drifting snow at the edges." "$S $G"
g title "Wide cinematic title painting with no text: a lone swordsman in a conical bamboo hat and vermilion scarf seen from behind on a cliff, facing misty layered mountains, a far pagoda and a huge pale red sun, lots of empty paper space in the upper left." "$S"
